INSERT INTO `fiche` (`ID`, `ID_CONSTRUCTEUR`, `ID_MODELE`, `ID_ANNEE_DEBUT`, `ID_ANNEE_FIN`, `ID_SEGMENT`, `NOM_FICHE`, `RESUME_FICHE`, `HISTOIRE_FICHE`, `DATE_AJOUT`, `ID_UTILISATEUR`) VALUES
                                                                                                                                                                                              (1, 5, 1, 1, 2, 3, 'Civic', 'Compacte sportive', '<p>La Civic est un modèle emblématique dans la catégorie des compactes. Connue pour son dynamisme et sa fiabilité, elle a évolué au fil des années pour intégrer les dernières technologies tout en conservant son caractère sportif.</p><p>La dernière version améliore le confort intérieur avec des matériaux de haute qualité et des options de connectivité avancées. La Civic offre également une conduite agile et une efficacité énergétique remarquable, ce qui en fait un choix populaire pour les conducteurs à la recherche d’un véhicule polyvalent.</p>', NOW(), 1),
                                                                                                                                                                                              (2, 5, 2, 1, 2, 4, 'Accord', 'Berline intermédiaire', '<p>L\'Accord est une berline intermédiaire reconnue pour son confort et sa qualité de conduite. Conçue pour offrir une expérience de conduite agréable, elle combine un design élégant avec des technologies modernes.</p><p>Les dernières versions de l\'Accord intègrent des améliorations notables en matière de sécurité, de performance et de confort, faisant de ce modèle un choix de premier ordre pour les familles et les professionnels.</p>', NOW(), 1),
                                                                                                                                                                                              (3, 6, 3, 1, 2, 5, 'Mustang', 'Coupé sportif', '<p>La Mustang est un coupé sportif iconique qui allie performance et style. Avec ses moteurs puissants et son design distinctif, elle est conçue pour offrir une conduite excitante et dynamique.</p><p>Les modèles récents continuent de repousser les limites avec des améliorations en termes de technologie et de confort, tout en maintenant l’essence même du sport automobile qui fait la renommée de la Mustang.</p>', NOW(), 1),
                                                                                                                                                                                              (4, 6, 4, 1, 2, 6, 'F-150', 'Pick-up robuste', '<p>Le F-150 est un pick-up robuste qui se distingue par sa capacité de chargement et ses performances tout-terrain. Conçu pour les tâches les plus exigeantes, il combine puissance et durabilité avec un confort accru pour les longues journées de travail.</p><p>Les dernières versions du F-150 intègrent des technologies avancées pour la sécurité et le confort, tout en continuant à offrir la robustesse qui a fait sa réputation.</p>', NOW(), 1),
                                                                                                                                                                                              (5, 7, 5, 1, 2, 7, 'Cherokee', 'SUV tout-terrain', '<p>Le Cherokee est un SUV tout-terrain qui allie confort et capacités de conduite en terrain difficile. Avec un design moderne et des caractéristiques de sécurité avancées, il est idéal pour les aventuriers et les familles.</p><p>Les modèles récents mettent l’accent sur l’amélioration de la technologie et du confort tout en conservant les compétences tout-terrain qui le définissent.</p>', NOW(), 1),
                                                                                                                                                                                              (6, 8, 6, 1, 2, 8, 'Grand Cherokee', 'SUV luxueux', '<p>Le Grand Cherokee est un SUV luxueux qui propose un intérieur raffiné et des caractéristiques de haute technologie. Avec ses capacités tout-terrain et son confort de conduite, il est conçu pour ceux qui recherchent à la fois luxe et performance.</p><p>Les dernières versions continuent d’améliorer le confort et la technologie tout en maintenant une excellente capacité tout-terrain.</p>', NOW(), 1),
                                                                                                                                                                                              (7, 9, 7, 1, 2, 1, 'Model S', 'Berline électrique', '<p>La Model S est une berline entièrement électrique qui offre des performances exceptionnelles et une autonomie impressionnante. Avec un design moderne et des caractéristiques de haute technologie, elle redéfinit le concept de la conduite électrique.</p><p>Les modèles récents continuent d’améliorer l’autonomie, la technologie et le confort, consolidant la position de la Model S comme une référence dans le marché des véhicules électriques.</p>', NOW(), 1),
                                                                                                                                                                                              (8, 10, 8, 1, 2, 2, 'Model X', 'SUV électrique', '<p>Le Model X est un SUV électrique qui combine luxe et innovation. Avec ses portes en ailes de faucon et ses caractéristiques de performance avancées, il offre une expérience de conduite unique.</p><p>Les versions récentes apportent des améliorations en matière de confort, de technologie et d’autonomie, offrant une alternative élégante aux SUV traditionnels.</p>', NOW(), 1),
                                                                                                                                                                                              (9, 11, 9, 1, 2, 3, 'Suburban', 'SUV grand format', '<p>Le Suburban est un SUV grand format qui offre un espace intérieur généreux et des capacités tout-terrain exceptionnelles. Conçu pour les familles et les aventuriers, il combine confort et fonctionnalité avec une performance robuste.</p><p>Les dernières versions améliorent le confort intérieur et la technologie tout en conservant ses capacités tout-terrain.</p>', NOW(), 1),
                                                                                                                                                                                              (10, 12, 10, 1, 2, 4, 'Silverado', 'Pick-up pleine grandeur', '<p>Le Silverado est un pick-up pleine grandeur qui se distingue par sa puissance et sa capacité de chargement. Avec un design robuste et des caractéristiques avancées, il est conçu pour les tâches les plus exigeantes.</p><p>Les modèles récents intègrent des technologies modernes pour le confort et la sécurité tout en maintenant une performance exceptionnelle.</p>', NOW(), 1),
                                                                                                                                                                                              (11, 13, 11, 1, 2, 5, 'Patriot', 'SUV compact', '<p>Le Patriot est un SUV compact qui allie style et fonctionnalité. Avec un design moderne et une capacité de conduite tout-terrain, il est parfait pour les aventures urbaines et rurales.</p><p>Les dernières versions mettent l’accent sur le confort et la technologie, offrant une expérience de conduite agréable et pratique.</p>', NOW(), 1),
                                                                                                                                                                                              (12, 14, 12, 1, 2, 6, 'Renegade', 'SUV compact', '<p>Le Renegade est un SUV compact qui offre une combinaison parfaite de style et de fonctionnalité. Avec ses caractéristiques modernes et son intérieur fonctionnel, il est idéal pour les conducteurs urbains et les aventuriers.</p><p>Les versions récentes continuent de renforcer ses capacités tout-terrain tout en offrant un confort amélioré.</p>', NOW(), 1),
                                                                                                                                                                                              (13, 15, 13, 1, 2, 7, 'F-Type', 'Coupé sportif', '<p>Le F-Type est un coupé sportif qui allie design élégant et performances exceptionnelles. Avec une gamme de moteurs puissants et un intérieur luxueux, il est conçu pour offrir une expérience de conduite exaltante.</p><p>Les modèles récents intègrent des technologies avancées et un confort accru pour les passionnés de conduite sportive.</p>', NOW(), 1),
                                                                                                                                                                                              (14, 16, 14, 1, 2, 8, 'XE', 'Berline sportive', '<p>Le XE est une berline sportive qui combine performances dynamiques et confort. Conçu pour les conducteurs recherchant une expérience de conduite active, il propose un design moderne et des caractéristiques haut de gamme.</p><p>Les versions récentes améliorent la technologie et la sécurité tout en offrant une conduite raffinée.</p>', NOW(), 1),
                                                                                                                                                                                              (15, 17, 15, 1, 2, 1, '488 Pista', 'Supercar', '<p>La 488 Pista est une supercar qui offre des performances exceptionnelles et un design aérodynamique. Conçue pour les passionnés de vitesse et de technologie, elle combine puissance brute et sophistication.</p><p>Les modèles récents intègrent des améliorations en matière de confort et de technologie tout en maintenant un design distinctif.</p>', NOW(), 1),
                                                                                                                                                                                              (16, 18, 16, 1, 2, 2, 'Stelvio', 'SUV sportif', '<p>Le Stelvio est un SUV sportif qui propose une combinaison unique de performance et de fonctionnalité. Conçu pour offrir une conduite dynamique tout en offrant un espace intérieur généreux, il est un choix populaire parmi les SUV de luxe.</p><p>Les modèles récents mettent l’accent sur la technologie et le confort, avec des caractéristiques modernes pour une expérience de conduite haut de gamme.</p>', NOW(), 1),
                                                                                                                                                                                              (17, 19, 17, 1, 2, 3, 'Focus', 'Compacte', '<p>La Focus est une compacte qui offre un excellent compromis entre performance et confort. Depuis ses débuts, elle a été conçue pour répondre aux besoins des conducteurs recherchant une conduite agile et une technologie avancée.</p><p>Les dernières versions continuent d’améliorer le confort et la technologie tout en maintenant une excellente performance sur route.</p>', NOW(), 1),
                                                                                                                                                                                              (18, 20, 18, 1, 2, 4, 'A6', 'Berline', '<p>L\'A6 est une berline qui combine luxe et performance. Avec un intérieur raffiné et des caractéristiques de conduite avancées, elle est conçue pour offrir un confort optimal et une expérience de conduite agréable.</p><p>Les modèles récents mettent l’accent sur les technologies modernes et les améliorations en matière de confort et de sécurité.</p>', NOW(), 1),
(19, 21, 19, 1, 2, 5, 'Q5', 'SUV', '<p>Le Q5 est un SUV qui allie confort et performance. Avec un design élégant et des caractéristiques modernes, il est conçu pour offrir une conduite agréable et un espace intérieur généreux.</p><p>Les versions récentes continuent de promouvoir l’innovation et le confort tout en offrant une conduite raffinée.</p>', NOW(), 1),
(20, 22, 20, 1, 2, 6, 'G-Class', 'SUV luxe', '<p>La G-Class est un SUV de luxe qui allie robustesse et sophistication. Avec son design emblématique et ses caractéristiques de conduite tout-terrain, elle est conçue pour ceux qui recherchent à la fois luxe et performance.</p><p>Les modèles récents améliorent le confort et la technologie tout en maintenant une excellente capacité tout-terrain.</p>', NOW(), 1),
(21, 23, 21, 1, 2, 7, 'X5', 'SUV premium', '<p>Le X5 est un SUV premium qui offre une expérience de conduite haut de gamme. Avec un intérieur luxueux et des performances exceptionnelles, il est conçu pour les conducteurs exigeants.</p><p>Les versions récentes mettent l’accent sur la technologie, le confort et la performance pour une expérience de conduite raffinée.</p>', NOW(), 1),
(22, 24, 22, 1, 2, 8, 'V60', 'Break', '<p>Le V60 est un break qui combine praticité et confort. Avec un design moderne et une capacité de chargement généreuse, il est idéal pour les familles et les conducteurs recherchant un véhicule spacieux.</p><p>Les modèles récents améliorent le confort intérieur et la technologie tout en offrant une performance équilibrée.</p>', NOW(), 1),
(23, 25, 23, 1, 2, 1, 'Panamera', 'Berline de luxe', '<p>La Panamera est une berline de luxe qui allie performance sportive et confort. Avec un design élégant et des caractéristiques haut de gamme, elle est conçue pour offrir une expérience de conduite exceptionnelle.</p><p>Les modèles récents continuent d’améliorer la technologie et le confort tout en offrant des performances remarquables.</p>', NOW(), 1),
(24, 26, 24, 1, 2, 2, 'Aston Martin DB11', 'Supercar', '<p>L\'Aston Martin DB11 est une supercar qui combine luxe et performance. Avec un design époustouflant et des caractéristiques de conduite avancées, elle est conçue pour offrir une expérience de conduite ultime.</p><p>Les modèles récents intègrent des technologies modernes pour le confort et la performance, faisant de la DB11 un choix exceptionnel dans le monde des supercars.</p>', NOW(), 1),
                                                                                                                                                                                              (25, 27, 25, 1, 2, 3, 'LaFerrari', 'Supercar', '<p>La LaFerrari est une supercar qui offre des performances inégalées et un design avant-gardiste. Conçue pour les passionnés de vitesse, elle combine puissance et technologie de pointe pour offrir une expérience de conduite unique.</p><p>Les modèles récents continuent d’améliorer les performances tout en offrant un confort et une sophistication exceptionnels.</p>', NOW(), 1),
                                                                                                                                                                                              (26, 28, 26, 1, 2, 4, 'F-PACE', 'SUV premium', '<p>Le F-PACE est un SUV premium qui propose un équilibre parfait entre performance et confort. Avec un design moderne et des caractéristiques de conduite avancées, il est idéal pour ceux qui recherchent une expérience de conduite haut de gamme.</p><p>Les versions récentes continuent de mettre l’accent sur la technologie et le confort, tout en offrant une performance exceptionnelle.</p>', NOW(), 1),
                                                                                                                                                                                              (27, 29, 27, 1, 2, 5, 'E-PACE', 'SUV compact', '<p>L\'E-PACE est un SUV compact qui allie style et performance. Avec un design moderne et des caractéristiques de conduite sportives, il est conçu pour offrir une expérience de conduite agréable tout en offrant une praticité accrue.</p><p>Les modèles récents intègrent des améliorations en matière de technologie et de confort tout en maintenant une performance dynamique.</p>', NOW(), 1),
(28, 30, 28, 1, 2, 6, 'I-PACE', 'SUV électrique', '<p>L\'I-PACE est un SUV électrique qui propose une conduite raffinée avec une autonomie impressionnante. Avec un design moderne et des caractéristiques haut de gamme, il est conçu pour offrir une expérience de conduite élégante et durable.</p><p>Les dernières versions mettent l’accent sur le confort et la technologie tout en offrant une performance électrique exceptionnelle.</p>', NOW(), 1),
                                                                                                                                                                                              (29, 31, 29, 1, 2, 7, 'Jetta', 'Berline compacte', '<p>Le Jetta est une berline compacte qui combine confort et performance. Avec un design moderne et des caractéristiques de conduite avancées, il est conçu pour offrir une expérience de conduite agréable et dynamique.</p><p>Les modèles récents continuent d’améliorer le confort et la technologie tout en maintenant une performance équilibrée.</p>', NOW(), 1),
                                                                                                                                                                                              (30, 32, 30, 1, 2, 8, 'Golf', 'Compacte', '<p>La Golf est une compacte qui allie style et performance. Avec un design élégant et des caractéristiques modernes, elle est conçue pour offrir une expérience de conduite agréable tout en restant pratique.</p><p>Les versions récentes intègrent des améliorations en matière de confort et de technologie tout en offrant une performance exceptionnelle.</p>', NOW(), 1),
                                                                                                                                                                                              (31, 33, 31, 1, 2, 1, 'X3', 'SUV', '<p>Le X3 est un SUV qui propose une expérience de conduite confortable et dynamique. Avec un design moderne et des caractéristiques de haute technologie, il est idéal pour ceux qui recherchent un SUV offrant à la fois luxe et performance.</p><p>Les dernières versions mettent l’accent sur le confort et la technologie tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (32, 34, 32, 1, 2, 2, 'X4', 'SUV compact', '<p>Le X4 est un SUV compact qui combine performance et design. Avec un intérieur raffiné et des caractéristiques de conduite sportives, il est idéal pour ceux qui recherchent une conduite dynamique et un confort élevé.</p><p>Les versions récentes améliorent la technologie et la sécurité tout en maintenant un design élégant.</p>', NOW(), 1),
                                                                                                                                                                                              (33, 35, 33, 1, 2, 3, 'X5', 'SUV premium', '<p>Le X5 est un SUV premium qui offre une expérience de conduite haut de gamme. Avec un intérieur luxueux et des performances exceptionnelles, il est conçu pour les conducteurs exigeants.</p><p>Les versions récentes mettent l’accent sur la technologie, le confort et la performance pour une expérience de conduite raffinée.</p>', NOW(), 1),
                                                                                                                                                                                              (34, 36, 34, 1, 2, 4, 'X6', 'SUV grand luxe', '<p>Le X6 est un SUV grand luxe qui allie performance et élégance. Avec son design distinctif et ses caractéristiques de confort haut de gamme, il est conçu pour ceux qui recherchent à la fois style et fonctionnalité.</p><p>Les modèles récents améliorent la technologie et le confort tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (35, 37, 35, 1, 2, 5, 'X7', 'SUV grand format', '<p>Le X7 est un SUV grand format qui offre un espace intérieur luxueux et des performances exceptionnelles. Conçu pour les familles et les aventuriers, il propose un confort inégalé et des caractéristiques modernes.</p><p>Les modèles récents intègrent des technologies de pointe pour le confort et la sécurité, tout en offrant un design moderne et imposant.</p>', NOW(), 1),
                                                                                                                                                                                              (36, 38, 36, 1, 2, 6, 'Q4 E-Tron', 'SUV électrique', '<p>Le Q4 E-Tron est un SUV compact électrique qui allie performance et praticité. Conçu pour offrir une expérience de conduite moderne avec une autonomie accrue, il propose des caractéristiques de confort et de technologie avancées.</p><p>Les versions récentes continuent de mettre l’accent sur l’efficacité énergétique tout en offrant un design élégant et moderne.</p>', NOW(), 1),
                                                                                                                                                                                              (37, 39, 37, 1, 2, 7, 'A3', 'Berline compacte', '<p>L\'A3 est une berline compacte qui combine luxe et performance. Avec un design moderne et des caractéristiques de conduite avancées, elle est conçue pour offrir une expérience de conduite dynamique et confortable.</p><p>Les modèles récents continuent de renforcer le confort et la technologie tout en offrant une performance équilibrée.</p>', NOW(), 1),
(38, 40, 38, 1, 2, 8, 'A4', 'Berline', '<p>L\'A4 est une berline qui allie performance et luxe. Avec un intérieur raffiné et des caractéristiques modernes, elle est conçue pour offrir un confort optimal et une conduite agréable.</p><p>Les versions récentes améliorent la technologie et le confort tout en maintenant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (39, 41, 39, 1, 2, 1, 'C-Class', 'Berline', '<p>La C-Class est une berline qui propose une combinaison parfaite de luxe et de performance. Avec un design élégant et des technologies avancées, elle est conçue pour offrir une expérience de conduite raffinée.</p><p>Les modèles récents mettent l’accent sur la technologie et le confort, tout en offrant des performances impressionnantes.</p>', NOW(), 1),
                                                                                                                                                                                              (40, 42, 40, 1, 2, 2, 'E-Class', 'Berline', '<p>L\'E-Class est une berline de luxe qui allie confort et technologie. Avec un intérieur spacieux et des caractéristiques modernes, elle est conçue pour offrir une conduite agréable et une expérience de luxe.</p><p>Les modèles récents continuent de renforcer le confort et la technologie tout en offrant des performances remarquables.</p>', NOW(), 1),
(41, 43, 41, 1, 2, 3, 'S-Class', 'Berline de luxe', '<p>L\'S-Class est une berline de luxe qui représente le summum du confort et de la technologie. Avec des caractéristiques haut de gamme et un design raffiné, elle est conçue pour offrir une expérience de conduite ultime.</p><p>Les dernières versions continuent d’améliorer la technologie et le confort tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (42, 44, 42, 1, 2, 4, 'GLS', 'SUV grand luxe', '<p>Le GLS est un SUV grand luxe qui propose un espace intérieur spacieux et des caractéristiques de confort avancées. Conçu pour les familles et les conducteurs exigeants, il combine performance et luxe.</p><p>Les modèles récents intègrent des améliorations en matière de confort et de technologie tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (43, 45, 43, 1, 2, 5, 'G-Class', 'SUV luxe', '<p>La G-Class est un SUV de luxe qui allie robustesse et sophistication. Avec son design emblématique et ses caractéristiques de conduite tout-terrain, elle est conçue pour ceux qui recherchent à la fois luxe et performance.</p><p>Les modèles récents améliorent le confort et la technologie tout en maintenant une excellente capacité tout-terrain.</p>', NOW(), 1),
                                                                                                                                                                                              (44, 46, 44, 1, 2, 6, '7 Series', 'Berline luxe', '<p>La 7 Series est une berline de luxe qui propose une expérience de conduite haut de gamme avec un intérieur spacieux et raffiné. Conçue pour offrir confort et technologie, elle est idéale pour les conducteurs exigeants.</p><p>Les dernières versions continuent d’améliorer le confort et la technologie tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (45, 47, 45, 1, 2, 7, '8 Series', 'Coupé luxe', '<p>L\'8 Series est un coupé luxe qui combine performance et élégance. Avec un design moderne et des caractéristiques de conduite avancées, elle est conçue pour offrir une expérience de conduite exceptionnelle.</p><p>Les modèles récents intègrent des technologies modernes pour le confort et la performance, consolidant ainsi la position de l\'8 Series comme une référence dans le monde des coupés de luxe.</p>', NOW(), 1),
                                                                                                                                                                                              (46, 48, 46, 1, 2, 8, 'M5', 'Berline sportive', '<p>La M5 est une berline sportive qui allie puissance et confort. Avec un design dynamique et des performances impressionnantes, elle est conçue pour offrir une expérience de conduite exaltante.</p><p>Les modèles récents continuent d’améliorer la technologie et le confort tout en offrant des performances exceptionnelles.</p>', NOW(), 1),
                                                                                                                                                                                              (47, 49, 47, 1, 2, 1, 'X1', 'SUV compact', '<p>Le X1 est un SUV compact qui propose une conduite agréable avec un design moderne et des caractéristiques de confort avancées. Idéal pour les conducteurs urbains, il combine praticité et style.</p><p>Les dernières versions intègrent des améliorations en matière de technologie et de confort, offrant une expérience de conduite raffinée.</p>', NOW(), 1),
                                                                                                                                                                                              (48, 50, 48, 1, 2, 2, 'Z4', 'Coupé sport', '<p>Le Z4 est un coupé sport qui allie performance et design. Avec un moteur puissant et un intérieur raffiné, il est conçu pour offrir une expérience de conduite dynamique.</p><p>Les modèles récents mettent l’accent sur le confort et la technologie tout en offrant des performances exceptionnelles sur route.</p>', NOW(), 1),
                                                                                                                                                                                              (49, 51, 49, 1, 2, 3, 'R8', 'Supercar', '<p>La R8 est une supercar qui propose des performances époustouflantes et un design innovant. Avec une puissance brute et une technologie de pointe, elle est conçue pour les passionnés de vitesse.</p><p>Les modèles récents continuent d’offrir des performances exceptionnelles tout en intégrant des améliorations en matière de confort et de technologie.</p>', NOW(), 1),
                                                                                                                                                                                              (50, 52, 50, 1, 2, 4, 'Taycan', 'Berline électrique', '<p>Le Taycan est une berline électrique qui offre des performances impressionnantes avec une autonomie élevée. Avec un design moderne et des caractéristiques de haute technologie, il est conçu pour les conducteurs à la recherche d’une expérience de conduite électrique raffinée.</p><p>Les versions récentes améliorent la technologie et le confort tout en offrant des performances de conduite exceptionnelles.</p>', NOW(), 1);
